import React, { useEffect, useState } from "react";
import axios from "axios";
import "../styles/main.css";

export default function FeeStructure() {
  const [fee, setFee] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    axios
      .get("http://localhost:5000/api/fees")
      .then((res) => {
        if (res.data.success) setFee(res.data.data);
      })
      .catch((err) => console.error("Error loading fee structure:", err))
      .finally(() => setLoading(false));
  }, []);

  if (loading) return <p className="loading-text">Loading fee structure...</p>;
  if (!fee) return <p className="loading-text">No fee data found.</p>;

  // Support categories or fallback to items
  const categories = fee.categories || [{ title: "Fees", items: fee.items || [] }];
  const grandTotal = categories.reduce(
    (sum, cat) => sum + (cat.items?.reduce((s, i) => s + (i.amount || 0), 0) || 0),
    0
  );

  return (
    <div className="page-container">
      <div className="fee-card">
        <h2 className="page-title">Fee Structure ({fee.academicYear})</h2>

        <div
          className="fee-description"
          dangerouslySetInnerHTML={{ __html: fee.notes }}
        />

        {categories.map((cat) => {
          const catTotal = cat.items?.reduce((sum, i) => sum + (i.amount || 0), 0) || 0;
          return (
            <div key={cat.title} className="fee-category">
              <h4>{cat.title}</h4>
              <table className="fee-table">
                <thead>
                  <tr>
                    <th>Particulars</th>
                    <th>Amount (₹)</th>
                  </tr>
                </thead>
                <tbody>
                  {cat.items.map((item) => (
                    <tr key={item._id || item.key || item.title}>
                      <td>{item.title}</td>
                      <td>₹{(item.amount || 0).toLocaleString()}</td>
                    </tr>
                  ))}
                  <tr className="total-row">
                    <td><strong>Category Total</strong></td>
                    <td><strong>₹{catTotal.toLocaleString()}</strong></td>
                  </tr>
                </tbody>
              </table>
            </div>
          );
        })}

        <p className="grand-total">
          <strong>Grand Total: ₹{grandTotal.toLocaleString()}</strong>
        </p>
      </div>
    </div>
  );
}






































































